#!/usr/bin/env python3
"""Normalize Polymarket market data into SignalRadar snapshot format.

Usage:
  python3 scripts/ingest_polymarket.py --input raw_markets.json --output cache/snapshots/polymarket.json
"""

from __future__ import annotations

import argparse
import json
import re
import urllib.request
from datetime import datetime, timezone
from typing import Any

from error_utils import emit_error


def slugify(text: str) -> str:
    lowered = text.strip().lower()
    lowered = re.sub(r"[^a-z0-9]+", "-", lowered)
    return lowered.strip("-") or "unknown"


def as_percent(value: Any) -> float | None:
    if value is None:
        return None
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    if v <= 1.0:
        return round(v * 100.0, 6)
    return round(v, 6)


def first_non_null(item: dict[str, Any], keys: list[str]) -> Any:
    for key in keys:
        if key in item and item[key] is not None:
            return item[key]
    return None


def normalize_item(item: dict[str, Any]) -> dict[str, Any] | None:
    market_id = first_non_null(item, ["id", "market_id", "marketId"])
    question = first_non_null(item, ["question", "title", "name"])
    if market_id is None or not question:
        return None

    probability = as_percent(
        first_non_null(
            item,
            [
                "probability",
                "current",
                "price",
                "lastPrice",
                "yesPrice",
            ],
        )
    )
    if probability is None:
        outcome_prices = item.get("outcomePrices")
        if isinstance(outcome_prices, str) and outcome_prices.startswith("["):
            try:
                outcome_prices = json.loads(outcome_prices)
            except (json.JSONDecodeError, ValueError):
                outcome_prices = None
        if isinstance(outcome_prices, list) and outcome_prices:
            probability = as_percent(outcome_prices[0])
    if probability is None:
        return None

    event_id = str(first_non_null(item, ["event_id", "eventId", "event", "parentEvent", "id"]) or market_id)
    status = str(first_non_null(item, ["status", "state"]) or "active")
    volume_24h = first_non_null(item, ["volume_24h", "volume24h", "volume", "liquidity"])
    end_date = first_non_null(item, ["endDate", "end_date", "closeTime"])

    return {
        "source": "polymarket",
        "market_id": str(market_id),
        "event_id": str(event_id),
        "slug": slugify(str(question)),
        "question": str(question),
        "probability": probability,
        "volume_24h": float(volume_24h) if volume_24h is not None else None,
        "status": status.lower(),
        "end_date": end_date,
        "ts": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
    }


def fetch_json(url: str, timeout: int) -> Any:
    req = urllib.request.Request(url, headers={"User-Agent": "signalradar-skill/1.0"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def load_input(args: argparse.Namespace) -> list[dict[str, Any]]:
    if args.input:
        with open(args.input, "r", encoding="utf-8") as f:
            payload = json.load(f)
    elif args.url:
        payload = fetch_json(args.url, args.timeout)
    else:
        raise ValueError("either --input or --url is required")

    if isinstance(payload, dict):
        for key in ["markets", "data", "items"]:
            if isinstance(payload.get(key), list):
                payload = payload[key]
                break
    if not isinstance(payload, list):
        raise ValueError("input payload must be a list or an object containing list data")
    return payload


def main() -> int:
    parser = argparse.ArgumentParser(description="Normalize Polymarket feed")
    parser.add_argument("--input", help="Path to raw JSON input")
    parser.add_argument("--url", help="Optional Polymarket URL to fetch")
    parser.add_argument("--timeout", type=int, default=15, help="HTTP timeout seconds")
    parser.add_argument("--output", required=True, help="Normalized snapshots JSON path")
    args = parser.parse_args()

    try:
        raw_items = load_input(args)
        normalized: list[dict[str, Any]] = []
        for item in raw_items:
            if not isinstance(item, dict):
                continue
            row = normalize_item(item)
            if row is not None:
                normalized.append(row)

        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(normalized, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print(f"wrote {len(normalized)} snapshots -> {args.output}")
        return 0
    except Exception as exc:  # noqa: BLE001
        return emit_error(
            "SR_SOURCE_UNAVAILABLE",
            f"ingest failed: {exc}",
            retryable=True,
            details={"script": "ingest_polymarket.py"},
        )


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Manage a Notion Database for SignalRadar watchlist display.

Provides functions to create, sync, and query a Notion Database that
mirrors the local watchlist markdown — but with proper table UI
(sortable, filterable) for users.
"""

from __future__ import annotations

import json
import urllib.request
import os
from typing import Any

from error_utils import emit_error


# ---------------------------------------------------------------------------
# Notion API helpers (aligned with pull_notion_watchlist_entries.py patterns)
# ---------------------------------------------------------------------------

NOTION_API_BASE = "https://api.notion.com/v1"
NOTION_API_VERSION = "2022-06-28"

DB_TITLE = "SignalRadar_Watchlist"
DB_ID_CACHE_NAME = ".notion_db_id"

# Select option colours
CATEGORY_COLORS: dict[str, str] = {
    "AI Releases": "blue",
    "AI Leaders": "purple",
    "OpenAI IPO": "green",
    "SpaceX IPO": "orange",
    "SpaceX Missions": "red",
    "Crypto": "yellow",
    "Geopolitics": "gray",
}


def notion_headers() -> dict[str, str]:
    key = os.environ.get("NOTION_API_KEY", "")
    return {
        "Authorization": f"Bearer {key}",
        "Notion-Version": NOTION_API_VERSION,
        "Content-Type": "application/json",
    }


def api_request(method: str, url: str, headers: dict[str, str], body: dict | None = None) -> dict[str, Any]:
    data = json.dumps(body, ensure_ascii=False).encode("utf-8") if body else None
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode("utf-8"))


def api_get(url: str, headers: dict[str, str]) -> dict[str, Any]:
    return api_request("GET", url, headers)


# ---------------------------------------------------------------------------
# Database schema definition
# ---------------------------------------------------------------------------

def _database_properties() -> dict[str, Any]:
    cat_options = [{"name": k, "color": v} for k, v in CATEGORY_COLORS.items()]
    return {
        "问题": {"title": {}},
        "分类": {
            "select": {"options": cat_options},
        },
        "Yes概率": {
            "number": {"format": "percent"},
        },
        "链接": {"url": {}},
        "Source": {
            "select": {
                "options": [
                    {"name": "auto", "color": "green"},
                    {"name": "manual", "color": "orange"},
                ],
            },
        },
    }


# ---------------------------------------------------------------------------
# Core functions
# ---------------------------------------------------------------------------

def find_child_page_id(
    parent_page_id: str,
    headers: dict[str, str],
    title_candidates: list[str],
) -> str | None:
    """Return the id of the first child page whose title is in *title_candidates*."""
    url = f"{NOTION_API_BASE}/blocks/{parent_page_id}/children?page_size=100"
    data = api_get(url, headers)
    for block in data.get("results", []):
        if block.get("type") == "child_page":
            t = block.get("child_page", {}).get("title", "")
            if t in title_candidates:
                return block["id"]
    return None


def find_database_under_page(
    parent_page_id: str,
    headers: dict[str, str],
    db_title: str = DB_TITLE,
) -> str | None:
    """Find an existing inline database under a page by title."""
    url = f"{NOTION_API_BASE}/blocks/{parent_page_id}/children?page_size=100"
    data = api_get(url, headers)
    for block in data.get("results", []):
        if block.get("type") == "child_database":
            t = block.get("child_database", {}).get("title", "")
            if t == db_title:
                return block["id"]
    return None


def create_watchlist_database(
    parent_page_id: str,
    headers: dict[str, str],
    title: str = DB_TITLE,
) -> str:
    """Create a new Notion Database under the given parent page."""
    payload = {
        "parent": {"type": "page_id", "page_id": parent_page_id},
        "title": [{"type": "text", "text": {"content": title}}],
        "is_inline": True,
        "properties": _database_properties(),
    }
    result = api_request("POST", f"{NOTION_API_BASE}/databases", headers, payload)
    return str(result.get("id", "")).strip()


def find_or_create_watchlist_db(
    root_page_id: str,
    headers: dict[str, str],
    title: str = DB_TITLE,
) -> str:
    """Find existing database or create a new one. Returns database_id."""
    db_id = find_database_under_page(root_page_id, headers, title)
    if db_id:
        return db_id
    return create_watchlist_database(root_page_id, headers, title)


def _build_row_properties(
    question: str,
    category: str = "",
    probability: float | None = None,
    url: str | None = None,
    source: str = "auto",
) -> dict[str, Any]:
    """Build Notion page properties dict for a database row."""
    props: dict[str, Any] = {
        "问题": {
            "title": [{"type": "text", "text": {"content": question}}],
        },
    }
    if category:
        props["分类"] = {"select": {"name": category}}
    if probability is not None:
        # Notion percent format expects 0-1 range.
        # Polymarket returns 0-100 (e.g. 45.5 means 45.5%).
        # Values >= 1.0 are treated as percentage and divided by 100.
        props["Yes概率"] = {"number": probability / 100.0 if probability >= 1.0 else probability}
    if url:
        props["链接"] = {"url": url}
    if source:
        props["Source"] = {"select": {"name": source}}
    return props


def query_all_rows(
    database_id: str,
    headers: dict[str, str],
) -> list[dict[str, Any]]:
    """Query all rows from the database with pagination."""
    all_rows: list[dict[str, Any]] = []
    cursor: str | None = None
    while True:
        payload: dict[str, Any] = {"page_size": 100}
        if cursor:
            payload["start_cursor"] = cursor
        resp = api_request("POST", f"{NOTION_API_BASE}/databases/{database_id}/query", headers, payload)
        all_rows.extend(resp.get("results", []))
        if not resp.get("has_more"):
            break
        cursor = resp.get("next_cursor")
        if not cursor:
            break
    return all_rows


def _extract_title(row: dict[str, Any]) -> str:
    """Extract the title text from a database row."""
    title_prop = row.get("properties", {}).get("问题", {})
    for rt in title_prop.get("title", []):
        return rt.get("text", {}).get("content", "")
    return ""


def _extract_url(row: dict[str, Any]) -> str:
    """Extract the URL from a database row."""
    return row.get("properties", {}).get("链接", {}).get("url", "") or ""


def _extract_select(row: dict[str, Any], prop: str) -> str:
    """Extract a select value from a database row."""
    sel = row.get("properties", {}).get(prop, {}).get("select")
    return sel.get("name", "") if sel else ""


def update_row_properties(
    page_id: str,
    headers: dict[str, str],
    props: dict[str, Any],
) -> None:
    """Update properties of an existing database row."""
    api_request("PATCH", f"{NOTION_API_BASE}/pages/{page_id}", headers, {"properties": props})


def sync_watchlist_to_db(
    database_id: str,
    headers: dict[str, str],
    items: list[dict[str, Any]],
) -> dict[str, int]:
    """Sync watchlist items to database. Creates new rows, updates existing.

    Returns {"created": N, "updated": M, "skipped": K}.
    """
    existing_rows = query_all_rows(database_id, headers)
    existing_map: dict[str, str] = {}  # question -> page_id
    for row in existing_rows:
        q = _extract_title(row).strip().lower()
        if q:
            existing_map[q] = row["id"]

    created = 0
    updated = 0
    skipped = 0

    for item in items:
        question = str(item.get("question", "")).strip()
        if not question:
            skipped += 1
            continue

        props = _build_row_properties(
            question=question,
            category=str(item.get("category", "")),
            probability=float(item.get("yes", 0)) if item.get("yes") is not None else None,
            source="auto",
        )

        key = question.lower()
        if key in existing_map:
            # Update existing row
            page_id = existing_map[key]
            try:
                api_request(
                    "PATCH",
                    f"{NOTION_API_BASE}/pages/{page_id}",
                    headers,
                    {"properties": props},
                )
                updated += 1
            except Exception:
                skipped += 1
        else:
            # Create new row
            try:
                api_request(
                    "POST",
                    f"{NOTION_API_BASE}/pages",
                    headers,
                    {
                        "parent": {"type": "database_id", "database_id": database_id},
                        "properties": props,
                    },
                )
                created += 1
            except Exception:
                skipped += 1

    return {"created": created, "updated": updated, "skipped": skipped}


def add_manual_entry_to_db(
    database_id: str,
    headers: dict[str, str],
    question: str,
    category: str = "",
    url: str | None = None,
) -> str | None:
    """Add a single manual entry to the database. Returns page_id or None."""
    # Check for duplicates
    existing = query_all_rows(database_id, headers)
    key = question.strip().lower()
    for row in existing:
        if _extract_title(row).strip().lower() == key:
            return None  # already exists

    props = _build_row_properties(
        question=question,
        category=category,
        url=url,
        source="manual",
    )
    result = api_request(
        "POST",
        f"{NOTION_API_BASE}/pages",
        headers,
        {
            "parent": {"type": "database_id", "database_id": database_id},
            "properties": props,
        },
    )
    return str(result.get("id", "")).strip()

#!/usr/bin/env python3
"""Refresh polymarket watchlist + rollover suggestions.

Supports custom workspace paths via args/env:
- SIGNALRADAR_WORKSPACE_ROOT
- --workspace-root
- --output-watchlist / --output-rollover / --state
"""

from __future__ import annotations

import argparse
import datetime
import hashlib
import json
import sys
import os
import re
import urllib.parse
import urllib.request
from difflib import SequenceMatcher
from pathlib import Path
from typing import Any

BASE = "https://gamma-api.polymarket.com/markets"
EVENT_BASE = "https://gamma-api.polymarket.com/events"
HEAD = {"User-Agent": "Mozilla/5.0", "Accept": "application/json"}

DEFAULT_KEYWORDS: dict[str, list[str]] = {
    "AI Releases": [
        "claude 5",
        "grok 5",
        "grok 4.20",
        "grok-4pt20",
        "gpt-6",
        "deepseek",
        "deepseek v4",
        "deepseek-v4",
        "gemini 3.5",
        "gemini-3pt5",
        "chatbot arena 1500",
    ],
    "AI Leaders": ["best ai model", "top ai model"],
    "OpenAI IPO": ["openai ipo", "openai's market cap", "openai not ipo by december 31, 2026"],
    "SpaceX IPO": ["spacex ipo", "no ipo before 2028", "spacex market cap"],
    "SpaceX Missions": ["starship flight test", "spacex starship"],
}

DEFAULT_MANUAL_MARKETS: list[dict[str, Any]] = [
    {
        "category": "SpaceX IPO",
        "question": "SpaceX IPO Closing Market Cap（手动跟踪）",
        "yes": 0.0,
        "vol24h": 0.0,
        "totalVol": 0.0,
        "endDate": "2027-12-31",
        "slug": "spacex-ipo-closing-market-cap",
        "watch_level": "normal",
        "threshold_abs_pp": None,
    },
    {
        "category": "AI Releases",
        "question": "Gemini 3.5 released by June 30?（手动跟踪）",
        "yes": 0.0,
        "vol24h": 0.0,
        "totalVol": 0.0,
        "endDate": "2026-06-30",
        "slug": "gemini-3pt5-released-by-june-30",
        "watch_level": "normal",
        "threshold_abs_pp": None,
    },
]


def default_workspace_root() -> str:
    env_root = os.environ.get("SIGNALRADAR_WORKSPACE_ROOT", "").strip()
    if env_root:
        return env_root
    try:
        script_root = Path(__file__).resolve().parent.parent.parent.parent
        if (script_root / "skills" / "signalradar" / "scripts").exists():
            return str(script_root)
    except Exception:
        pass
    return str(Path.cwd())


def load_keywords_config(path: Path | None) -> tuple[dict[str, list[str]], list[dict[str, Any]]]:
    """Load keywords and manual_markets from external config file.

    Returns (keywords, manual_markets). Falls back to defaults if file
    does not exist or is invalid.
    """
    if path is None or not path.exists():
        return dict(DEFAULT_KEYWORDS), list(DEFAULT_MANUAL_MARKETS)
    try:
        obj = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return dict(DEFAULT_KEYWORDS), list(DEFAULT_MANUAL_MARKETS)
    if not isinstance(obj, dict):
        return dict(DEFAULT_KEYWORDS), list(DEFAULT_MANUAL_MARKETS)
    keywords = obj.get("keywords", DEFAULT_KEYWORDS)
    if not isinstance(keywords, dict):
        keywords = dict(DEFAULT_KEYWORDS)
    manual = obj.get("manual_markets", DEFAULT_MANUAL_MARKETS)
    if not isinstance(manual, list):
        manual = list(DEFAULT_MANUAL_MARKETS)
    return keywords, manual

STOPWORDS = set("will the a an by on before after between and or be released release at of for in to".split())


def fetch_json(url: str) -> Any:
    req = urllib.request.Request(url, headers=HEAD)
    with urllib.request.urlopen(req, timeout=20) as resp:
        return json.loads(resp.read().decode("utf-8"))


def fetch_all(limit: int = 500, max_pages: int = 6) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for i in range(max_pages):
        q = urllib.parse.urlencode({"active": "true", "closed": "false", "limit": str(limit), "offset": str(i * limit)})
        arr = fetch_json(f"{BASE}?{q}")
        if not arr:
            break
        rows.extend([x for x in arr if isinstance(x, dict)])
    return rows


def fetch_events(limit: int = 200, max_pages: int = 10) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for i in range(max_pages):
        q = urllib.parse.urlencode({"active": "true", "closed": "false", "limit": str(limit), "offset": str(i * limit)})
        arr = fetch_json(f"{EVENT_BASE}?{q}")
        if not arr:
            break
        rows.extend([x for x in arr if isinstance(x, dict)])
    return rows


def yes_prob(m: dict[str, Any]) -> float:
    try:
        return float(json.loads(m.get("outcomePrices", '["0","0"]'))[0]) * 100
    except Exception:
        return 0.0


def norm_text(s: str) -> str:
    s = s.lower()
    s = re.sub(r"\b\d{4}\b", " ", s)
    s = re.sub(r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b", " ", s)
    s = re.sub(r"[^a-z0-9 ]+", " ", s)
    toks = [t for t in s.split() if t not in STOPWORDS and len(t) > 2]
    return " ".join(toks)


def parse_date(s: str) -> datetime.date | None:
    try:
        return datetime.date.fromisoformat((s or "")[:10])
    except Exception:
        return None


def extract_signature(q: str) -> dict[str, set[str]]:
    ql = (q or "").lower()
    tokens = set(norm_text(ql).split())
    entities = {k for k in ["claude", "grok", "gpt", "deepseek", "gemini", "openai", "spacex", "starship", "ipo"] if k in ql}
    horizon = {k for k in ["feb", "march", "april", "june", "december", "2026", "2027"] if k in ql}
    return {"tokens": tokens, "entities": entities, "horizon": horizon}


def rollover_score(prev_item: dict[str, Any], cand_q: str, cand_end: str, cand_cat: str) -> float:
    p_sig = extract_signature(str(prev_item.get("question", "")))
    c_sig = extract_signature(cand_q)
    text_sim = SequenceMatcher(None, norm_text(str(prev_item.get("question", ""))), norm_text(cand_q)).ratio()
    tok_j = 0.0
    if p_sig["tokens"] or c_sig["tokens"]:
        inter = len(p_sig["tokens"] & c_sig["tokens"])
        uni = max(1, len(p_sig["tokens"] | c_sig["tokens"]))
        tok_j = inter / uni
    ent_bonus = 0.15 if (p_sig["entities"] & c_sig["entities"]) else 0.0
    hor_bonus = 0.05 if (p_sig["horizon"] & c_sig["horizon"]) else 0.0
    cat_bonus = 0.08 if str(prev_item.get("category")) == cand_cat else 0.0
    date_bonus = 0.0
    pd = parse_date(str(prev_item.get("endDate", "")))
    cd = parse_date(cand_end)
    if pd and cd:
        delta = abs((cd - pd).days)
        if delta <= 45:
            date_bonus = 0.08
        elif delta <= 120:
            date_bonus = 0.04
    return 0.45 * text_sim + 0.35 * tok_j + ent_bonus + hor_bonus + cat_bonus + date_bonus


def add_item(cat: str, m: dict[str, Any], seen: set[str], cat_items: list[dict[str, Any]]) -> None:
    text = (str(m.get("question", "")) + " " + str(m.get("description", ""))).lower()
    q = str(m.get("question", "")).strip()
    if not q or q in seen:
        return
    if "gemini 3" in text and "feb" in text:
        return
    ed = str(m.get("endDate") or "")[:10]
    if ed:
        try:
            if datetime.date.fromisoformat(ed) < datetime.datetime.now(datetime.timezone.utc).date():
                return
        except Exception:
            pass
    if cat in ("SpaceX IPO", "SpaceX Missions") and "spacex" not in text:
        return
    if cat == "OpenAI IPO" and "openai" not in text:
        return
    cat_items.append(
        {
            "category": cat,
            "question": q,
            "yes": round(yes_prob(m), 2),
            "vol24h": float(m.get("volume24hr") or 0),
            "totalVol": float(m.get("volumeNum") or 0),
            "endDate": ed,
            "slug": str(m.get("slug", "")),
            "watch_level": "normal",
            "threshold_abs_pp": None,
        }
    )
    seen.add(q)


def pick(
    markets: list[dict[str, Any]],
    events: list[dict[str, Any]],
    keywords: dict[str, list[str]] | None = None,
    manual_markets: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    kw = keywords if keywords is not None else DEFAULT_KEYWORDS
    mm = manual_markets if manual_markets is not None else DEFAULT_MANUAL_MARKETS
    selected: list[dict[str, Any]] = []
    seen: set[str] = set()
    for cat, terms in kw.items():
        cat_items: list[dict[str, Any]] = []
        for m in markets:
            text = (str(m.get("question", "")) + " " + str(m.get("description", ""))).lower()
            if any(t in text for t in terms):
                add_item(cat, m, seen, cat_items)
        for e in events:
            etext = (str(e.get("title", "")) + " " + str(e.get("description", "")) + " " + str(e.get("slug", ""))).lower()
            if any(t in etext for t in terms):
                for m in (e.get("markets") or []):
                    if isinstance(m, dict):
                        add_item(cat, m, seen, cat_items)
        cat_items.sort(key=lambda x: float(x.get("vol24h", 0)), reverse=True)
        selected.extend(cat_items[:20])
    existing_slugs = {str(i.get("slug", "")) for i in selected}
    for m in mm:
        if str(m.get("slug", "")) not in existing_slugs:
            selected.append(dict(m))
    return selected


def render(items: list[dict[str, Any]]) -> str:
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    lines = [
        "# Polymarket 2026 科技主题监控清单",
        "",
        f"- 更新时间(UTC): {now}",
        "- 规则：列表变化时触发提醒；无变化不提醒。",
        "- 说明：已移除 Gemini 3 2月底相关旧市场（若已接近结算/失真）。",
        "",
        "| 分类 | 问题 | Yes概率 | 24h成交额 | 总成交额 | 截止日 | WatchLevel | ThresholdPP |",
        "|---|---|---:|---:|---:|---|---|---:|",
    ]
    for x in items:
        watch_level = str(x.get("watch_level", "normal")).lower()
        threshold = x.get("threshold_abs_pp")
        threshold_text = ""
        if isinstance(threshold, (int, float)) and float(threshold) > 0:
            threshold_text = f"{float(threshold):.2f}"
        lines.append(
            f"| {x.get('category')} | {str(x.get('question','')).replace('|','/')} | {float(x.get('yes',0)):.2f}% | "
            f"${float(x.get('vol24h',0)):,.0f} | ${float(x.get('totalVol',0)):,.0f} | {x.get('endDate','')} | {watch_level} | {threshold_text} |"
        )
    return "\n".join(lines) + "\n"


def build_rollover(prev_items: list[dict[str, Any]], new_items: list[dict[str, Any]], pool: list[dict[str, Any]]) -> str:
    prev = {(i.get("slug") or i.get("question")): i for i in prev_items if isinstance(i, dict)}
    new_keys = {(i.get("slug") or i.get("question")) for i in new_items}
    removed = [v for k, v in prev.items() if k not in new_keys]
    lines = [
        "# Polymarket 关闭/迁移继任建议",
        "",
        f"- 更新时间(UTC): {datetime.datetime.now(datetime.timezone.utc).isoformat()}",
        "",
    ]
    if not removed:
        lines.append("无关闭/迁移候选。")
        return "\n".join(lines) + "\n"
    for r in removed[:20]:
        q = str(r.get("question", ""))
        cat = str(r.get("category", "Unknown"))
        cands: list[tuple[float, str, str, str]] = []
        for m in pool:
            qq = str(m.get("question", ""))
            if not qq:
                continue
            score = rollover_score(r, qq, str(m.get("endDate") or "")[:10], cat)
            if score >= 0.52:
                cands.append((score, qq, str(m.get("slug", "")), str(m.get("endDate") or "")[:10]))
        cands = sorted(cands, key=lambda x: x[0], reverse=True)[:5]
        lines.append(f"## 关闭/移除: {q}")
        lines.append(f"- 分类: {cat}")
        if not cands:
            lines.append("- 继任候选: 未找到（保留手动跟踪）")
        else:
            lines.append("- 继任候选:")
            for s, qq, slug, ed in cands:
                lines.append(f"  - ({s:.2f}) {qq} | end={ed} | slug={slug}")
        lines.append("")
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description="Refresh polymarket watchlist + rollover")
    parser.add_argument("--workspace-root", default=default_workspace_root())
    parser.add_argument("--output-watchlist", default="")
    parser.add_argument("--output-rollover", default="")
    parser.add_argument("--state", default="")
    parser.add_argument("--market-limit", type=int, default=500)
    parser.add_argument("--market-max-pages", type=int, default=6)
    parser.add_argument("--event-limit", type=int, default=200)
    parser.add_argument("--event-max-pages", type=int, default=10)
    parser.add_argument("--keywords-config", default="", help="Path to watchlist_keywords.json (optional, falls back to defaults)")
    parser.add_argument("--dry-run", action="store_true", help="Preview entries without writing files")
    args = parser.parse_args()

    root = Path(args.workspace_root)
    out_md = Path(args.output_watchlist) if args.output_watchlist else root / "memory" / "polymarket_watchlist_2026.md"
    rollover_md = Path(args.output_rollover) if args.output_rollover else root / "memory" / "polymarket_rollover_2026.md"
    state = Path(args.state) if args.state else root / "cache" / "polymarket" / "watchlist_state.json"

    kw_path = Path(args.keywords_config) if args.keywords_config else None
    keywords, manual_markets = load_keywords_config(kw_path)

    out_md.parent.mkdir(parents=True, exist_ok=True)
    rollover_md.parent.mkdir(parents=True, exist_ok=True)
    state.parent.mkdir(parents=True, exist_ok=True)

    markets = fetch_all(limit=args.market_limit, max_pages=args.market_max_pages)
    events = fetch_events(limit=args.event_limit, max_pages=args.event_max_pages)
    items = pick(markets, events, keywords=keywords, manual_markets=manual_markets)

    # Show count per category for transparency
    cat_counts: dict[str, int] = {}
    for item in items:
        cat = str(item.get("category", "Unknown"))
        cat_counts[cat] = cat_counts.get(cat, 0) + 1
    breakdown = ", ".join(f"{c}: {n}" for c, n in sorted(cat_counts.items()))
    print(f"Watchlist will contain {len(items)} entries ({breakdown})", file=sys.stderr)

    if args.dry_run:
        print(f"DRY_RUN count={len(items)}")
        for item in items:
            print(f"  [{item.get('category')}] {item.get('question')} ({item.get('yes', 0):.1f}%)")
        return 0

    pool = list(markets)
    for e in events:
        for m in (e.get("markets") or []):
            if isinstance(m, dict):
                pool.append(m)

    old_hash = ""
    prev_items: list[dict[str, Any]] = []
    if state.exists():
        try:
            st = json.loads(state.read_text(encoding="utf-8"))
            old_hash = str(st.get("hash", ""))
            prev_items = st.get("items", []) if isinstance(st.get("items", []), list) else []
        except Exception:
            pass

    md = render(items)
    rollover = build_rollover(prev_items, items, pool)
    out_md.write_text(md, encoding="utf-8")
    rollover_md.write_text(rollover, encoding="utf-8")

    new_hash = hashlib.md5((md + "\n---\n" + rollover).encode()).hexdigest()
    state.write_text(
        json.dumps(
            {
                "hash": new_hash,
                "updatedAt": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "count": len(items),
                "items": items,
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    if new_hash == old_hash:
        print("NO_CHANGE")
    else:
        print(f"CHANGED count={len(items)} file={out_md} rollover={rollover_md}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Pull manual watchlist entries from a Notion page and merge into watchlist markdown.

Expected manual line formats in Notion page:
- Category | Question
- Category | Question | EndDate(YYYY-MM-DD)
- Question
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
import urllib.error
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from error_utils import emit_error


DEFAULT_TITLE_CANDIDATES = [
    "SignalRadar_Manual_Entries",
    "SignalRadar Manual Entries",
    "Polymarket_Manual_Entries",
    "Polymarket Manual Entries",
]
DEFAULT_ROOT_TITLE_CANDIDATES = [
    "SignalRadar",
    "Signal Radar",
    "signalradar",
]
LEGACY_TOP_LEVEL_PAGE_TITLES = {
    "SignalRadar_系统目录",
    "polymarket_watchlist_2026",
    "polymarket_rollover_2026",
    "signalradar_monitor_jobs",
}
TEXT_BLOCK_TYPES = {
    "paragraph",
    "bulleted_list_item",
    "numbered_list_item",
    "to_do",
    "quote",
    "toggle",
}

ALLOWED_CATEGORIES = {
    "AI Releases",
    "AI Leaders",
    "OpenAI IPO",
    "SpaceX IPO",
    "SpaceX Missions",
    "Crypto",
    "Geopolitics",
}
WATCH_LEVELS = {"normal", "important"}
POLYMARKET_URL_RE = re.compile(r"https?://[^\s|]+")
POLYMARKET_SLUG_RE = re.compile(r"/(?:event|market)/([a-z0-9-]+)")


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def notion_headers() -> dict[str, str]:
    api_key = os.environ.get("NOTION_API_KEY", "").strip()
    if not api_key:
        raise ValueError("NOTION_API_KEY is not set")
    return {
        "Authorization": f"Bearer {api_key}",
        "Notion-Version": os.environ.get("NOTION_API_VERSION", "2022-06-28"),
        "Content-Type": "application/json",
    }


def api_request(method: str, url: str, headers: dict[str, str], payload: dict[str, Any] | None = None) -> dict[str, Any]:
    body = None
    if payload is not None:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(url, headers=headers, method=method, data=body)
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        msg = exc.read().decode("utf-8", errors="ignore")
        raise RuntimeError(f"notion http error {exc.code}: {msg}") from exc


def api_get(url: str, headers: dict[str, str]) -> dict[str, Any]:
    return api_request("GET", url, headers, None)


def fetch_public_json(url: str) -> Any:
    req = urllib.request.Request(url, headers={"User-Agent": "signalradar/1.0"}, method="GET")
    with urllib.request.urlopen(req, timeout=20) as resp:
        return json.loads(resp.read().decode("utf-8"))


def list_block_children(block_id: str, headers: dict[str, str]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor = ""
    while True:
        url = f"https://api.notion.com/v1/blocks/{block_id}/children?page_size=100"
        if cursor:
            url += f"&start_cursor={cursor}"
        payload = api_get(url, headers)
        rows = payload.get("results", [])
        if isinstance(rows, list):
            out.extend([x for x in rows if isinstance(x, dict)])
        if not payload.get("has_more"):
            break
        cursor = str(payload.get("next_cursor", "")).strip()
        if not cursor:
            break
    return out


def code_block(text: str) -> dict[str, Any]:
    return {
        "object": "block",
        "type": "code",
        "code": {
            "language": "plain text",
            "rich_text": [
                {
                    "type": "text",
                    "text": {"content": text},
                }
            ],
        },
    }


def manual_page_seed_children() -> list[dict[str, Any]]:
    return [
        code_block(
            "\n".join(
                [
                    "signalradar.page = SignalRadar_Manual_Entries",
                    "purpose = 用户手动新增监测条目（会回流到 watchlist）",
                    "editable = yes",
                    "format = 每行一个，格式如下：",
                    "  Category | Question | EndDate | WatchLevel | ThresholdPP",
                    "  （后三项可选；也支持直接粘贴 Polymarket URL）",
                    "notes = 乱格式行会被跳过；已存在条目不会重复新增",
                ]
            )
        ),
        {
            "object": "block",
            "type": "bulleted_list_item",
            "bulleted_list_item": {
                "rich_text": [
                    {
                        "type": "text",
                        "text": {
                            "content": "AI Releases | Will GPT-6 be released by June 30, 2026? | 2026-06-30 | important | 4.0"
                        },
                    }
                ]
            },
        },
        {
            "object": "block",
            "type": "bulleted_list_item",
            "bulleted_list_item": {
                "rich_text": [
                    {
                        "type": "text",
                        "text": {"content": "https://polymarket.com/event/will-openai-release-gpt-6-before-july-2026"},
                    }
                ]
            },
        },
    ]


def root_page_seed_children() -> list[dict[str, Any]]:
    return [
        code_block(
            "\n".join(
                [
                    "signalradar.page = SignalRadar",
                    "purpose = SignalRadar 目录页",
                    "editable = limited",
                    "notes = 建议保留目录结构，不要随意删除子页面",
                ]
            )
        ),
    ]


def append_children(page_id: str, headers: dict[str, str], children: list[dict[str, Any]]) -> None:
    if not children:
        return
    payload = {"children": children}
    api_request("PATCH", f"https://api.notion.com/v1/blocks/{page_id}/children", headers, payload)


def archive_block(block_id: str, headers: dict[str, str]) -> None:
    api_request("PATCH", f"https://api.notion.com/v1/blocks/{block_id}", headers, {"archived": True})


def bulleted_item_block(text: str) -> dict[str, Any]:
    return {
        "object": "block",
        "type": "bulleted_list_item",
        "bulleted_list_item": {
            "rich_text": [
                {
                    "type": "text",
                    "text": {"content": text},
                }
            ]
        },
    }


def create_child_page(parent_page_id: str, headers: dict[str, str], title: str) -> str:
    payload = {
        "parent": {"page_id": parent_page_id},
        "properties": {
            "title": {"title": [{"text": {"content": title}}]},
        },
    }
    created = api_request("POST", "https://api.notion.com/v1/pages", headers, payload)
    return str(created.get("id", "")).strip()


def create_manual_page(parent_page_id: str, headers: dict[str, str], title: str) -> str:
    page_id = create_child_page(parent_page_id, headers, title)
    if not page_id:
        return ""
    try:
        append_children(page_id, headers, manual_page_seed_children())
    except Exception:
        pass
    return page_id


def seed_manual_page_if_empty(page_id: str, headers: dict[str, str]) -> bool:
    blocks = list_block_children(page_id, headers)
    if blocks:
        return False
    append_children(page_id, headers, manual_page_seed_children())
    return True


def seed_root_page_if_empty(page_id: str, headers: dict[str, str]) -> bool:
    blocks = list_block_children(page_id, headers)
    if blocks:
        return False
    append_children(page_id, headers, root_page_seed_children())
    return True


def has_signalradar_code_header(block: dict[str, Any]) -> bool:
    if str(block.get("type", "")) != "code":
        return False
    code_obj = block.get("code")
    if not isinstance(code_obj, dict):
        return False
    text = rich_text_to_plain(code_obj.get("rich_text"))
    return "signalradar.page" in text.lower()


def ensure_manual_page_header(page_id: str, headers: dict[str, str]) -> bool:
    blocks = list_block_children(page_id, headers)
    if not blocks:
        return False
    if has_signalradar_code_header(blocks[0]):
        return False

    existing_lines = [extract_line_from_block(b) for b in blocks]
    cleaned_lines: list[str] = []
    seen: set[str] = set()
    for raw in existing_lines:
        line = raw.strip()
        if not line:
            continue
        if parse_line_to_entry(line) is None and not POLYMARKET_URL_RE.search(line):
            continue
        lowered = line.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        cleaned_lines.append(line)

    for block in blocks:
        block_id = str(block.get("id", "")).strip()
        if not block_id:
            continue
        try:
            archive_block(block_id, headers)
        except Exception:
            continue

    children = [manual_page_seed_children()[0]]
    if cleaned_lines:
        children.extend([bulleted_item_block(x) for x in cleaned_lines[:100]])
    else:
        children.extend(manual_page_seed_children()[1:])
    append_children(page_id, headers, children)
    return True


def rich_text_to_plain(rt: Any) -> str:
    if not isinstance(rt, list):
        return ""
    parts: list[str] = []
    for node in rt:
        if not isinstance(node, dict):
            continue
        text = node.get("plain_text")
        if isinstance(text, str):
            parts.append(text)
    return "".join(parts).strip()


def extract_line_from_block(block: dict[str, Any]) -> str:
    btype = str(block.get("type", ""))
    if not btype:
        return ""
    if btype not in TEXT_BLOCK_TYPES:
        return ""
    obj = block.get(btype)
    if not isinstance(obj, dict):
        return ""
    if "rich_text" in obj:
        return rich_text_to_plain(obj.get("rich_text"))
    return ""


def find_child_page_id(parent_page_id: str, headers: dict[str, str], title_candidates: list[str]) -> str:
    children = list_block_children(parent_page_id, headers)
    normalized = {c.lower().strip() for c in title_candidates if c and c.strip()}
    for block in children:
        if block.get("type") != "child_page":
            continue
        cp = block.get("child_page", {})
        title = str(cp.get("title", "")).strip()
        if title.lower() in normalized:
            return str(block.get("id", ""))
    return ""


def move_page_to_parent(page_id: str, new_parent_page_id: str, headers: dict[str, str]) -> bool:
    payload = {"parent": {"page_id": new_parent_page_id}}
    try:
        api_request("PATCH", f"https://api.notion.com/v1/pages/{page_id}", headers, payload)
    except Exception:
        return False
    try:
        page = api_get(f"https://api.notion.com/v1/pages/{page_id}", headers)
        parent = page.get("parent", {})
        if isinstance(parent, dict) and str(parent.get("page_id", "")).strip() == new_parent_page_id:
            return True
        return False
    except Exception:
        return False


def archive_page(page_id: str, headers: dict[str, str]) -> bool:
    try:
        api_request("PATCH", f"https://api.notion.com/v1/pages/{page_id}", headers, {"archived": True})
    except Exception:
        return False
    return True


def extract_manual_candidate_lines(page_id: str, headers: dict[str, str]) -> list[str]:
    blocks = list_block_children(page_id, headers)
    out: list[str] = []
    seen: set[str] = set()
    for block in blocks:
        line = extract_line_from_block(block).strip()
        if not line:
            continue
        if parse_line_to_entry(line) is None and not POLYMARKET_URL_RE.search(line):
            continue
        lowered = line.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        out.append(line)
    return out


def append_manual_entry_lines(page_id: str, headers: dict[str, str], lines: list[str]) -> None:
    if not lines:
        return
    children = [bulleted_item_block(x) for x in lines[:100]]
    append_children(page_id, headers, children)


def archive_legacy_top_level_pages(
    parent_page_id: str,
    root_page_id: str,
    headers: dict[str, str],
    manual_title_candidates: list[str],
) -> None:
    if parent_page_id == root_page_id:
        return
    keep_titles = {x.strip().lower() for x in manual_title_candidates if x and x.strip()}
    legacy_titles = {x.lower() for x in LEGACY_TOP_LEVEL_PAGE_TITLES}
    for block in list_block_children(parent_page_id, headers):
        if block.get("type") != "child_page":
            continue
        page_id = str(block.get("id", "")).strip()
        if not page_id or page_id == root_page_id:
            continue
        cp = block.get("child_page", {})
        title = str(cp.get("title", "")).strip()
        lowered = title.lower()
        if lowered in legacy_titles or lowered in keep_titles:
            archive_page(page_id, headers)


def normalize_category(raw: str) -> str:
    text = raw.strip()
    if text in ALLOWED_CATEGORIES:
        return text
    lowered = text.lower()
    if "ai release" in lowered:
        return "AI Releases"
    if "ai leader" in lowered or "top ai" in lowered or "best ai" in lowered:
        return "AI Leaders"
    if "openai" in lowered and "ipo" in lowered:
        return "OpenAI IPO"
    if "spacex" in lowered and "mission" in lowered:
        return "SpaceX Missions"
    if "spacex" in lowered and "ipo" in lowered:
        return "SpaceX IPO"
    if "crypto" in lowered:
        return "Crypto"
    if "geo" in lowered or "politic" in lowered:
        return "Geopolitics"
    return "AI Releases"


def infer_category_from_question(question: str) -> str:
    q = question.lower()
    if "spacex" in q and ("launch" in q or "starship" in q or "mission" in q):
        return "SpaceX Missions"
    if "spacex" in q and "ipo" in q:
        return "SpaceX IPO"
    if "openai" in q and "ipo" in q:
        return "OpenAI IPO"
    if any(k in q for k in ["best ai", "top ai model", "ai leader"]):
        return "AI Leaders"
    if any(k in q for k in ["crypto", "bitcoin", "btc", "ethereum", "eth", "solana"]):
        return "Crypto"
    if any(k in q for k in ["ukraine", "russia", "israel", "gaza", "taiwan", "election", "war"]):
        return "Geopolitics"
    return "AI Releases"


def parse_slug_from_url(url: str) -> str:
    m = POLYMARKET_SLUG_RE.search(url.lower())
    if not m:
        return ""
    return m.group(1).strip()


def fetch_market_by_slug(slug: str) -> dict[str, Any] | None:
    if not slug:
        return None
    candidates = [
        f"https://gamma-api.polymarket.com/markets?slug={slug}",
        f"https://gamma-api.polymarket.com/markets?active=true&closed=false&limit=2000",
    ]
    for url in candidates:
        try:
            payload = fetch_public_json(url)
        except Exception:
            continue
        if not isinstance(payload, list):
            continue
        row = None
        if "slug=" in url:
            row = payload[0] if payload else None
        else:
            for item in payload:
                if not isinstance(item, dict):
                    continue
                if str(item.get("slug", "")).strip().lower() == slug.lower():
                    row = item
                    break
        if not isinstance(row, dict):
            continue
        question = str(row.get("question", "") or row.get("title", "")).strip()
        if not question:
            continue
        end_date = str(row.get("endDate", "") or row.get("closeTime", "") or "")[:10]
        category = infer_category_from_question(question)
        return {
            "category": category,
            "question": question,
            "end_date": end_date,
            "watch_level": "normal",
            "threshold_abs_pp": None,
        }
    return None


def parse_line_to_entry(line: str) -> dict[str, Any] | None:
    text = line.strip().replace("｜", "|").strip()
    text = text.strip("“”\"'").lstrip("-•*").strip()
    if not text:
        return None
    if text.startswith("#"):
        return None
    lowered = text.lower()
    if "format:" in lowered or "格式：" in text or "每行一个" in text:
        return None
    parts = [p.strip() for p in text.strip("|").split("|")]
    parts = [p for p in parts if p]
    if len(parts) >= 2:
        category = normalize_category(parts[0])
        question = parts[1]
        end_date = parts[2] if len(parts) >= 3 else ""
        watch_level = parts[3] if len(parts) >= 4 else "normal"
        threshold_raw = parts[4] if len(parts) >= 5 else ""
    else:
        category = "AI Releases"
        question = parts[0]
        end_date = ""
        watch_level = "normal"
        threshold_raw = ""
    if not question:
        return None
    if re.match(r"(?i)^question$", question):
        return None
    if question.startswith("http://") or question.startswith("https://"):
        category = "AI Releases"
    end_date = end_date.strip()
    if end_date and not re.match(r"^\d{4}-\d{2}-\d{2}$", end_date):
        end_date = ""
    watch_level = watch_level.strip().lower()
    if watch_level not in WATCH_LEVELS:
        watch_level = "normal"
    threshold_abs_pp = None
    threshold_text = threshold_raw.strip().replace("%", "")
    if threshold_text:
        try:
            threshold_val = float(threshold_text)
            if threshold_val > 0:
                threshold_abs_pp = threshold_val
        except ValueError:
            threshold_abs_pp = None
    return {
        "category": category,
        "question": question,
        "end_date": end_date,
        "watch_level": watch_level,
        "threshold_abs_pp": threshold_abs_pp,
    }


def parse_manual_entries(lines: list[str]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for line in lines:
        entry = parse_line_to_entry(line)
        if entry is None:
            continue
        # Allow users to paste Polymarket URL directly.
        url_match = POLYMARKET_URL_RE.search(entry["question"])
        if url_match:
            slug = parse_slug_from_url(url_match.group(0))
            resolved = fetch_market_by_slug(slug)
            if resolved is not None:
                entry = resolved
            else:
                continue
        key = entry["question"].strip().lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(entry)
    return out


def parse_existing_questions(watchlist_lines: list[str]) -> set[str]:
    out: set[str] = set()
    for line in watchlist_lines:
        line = line.strip()
        if not line.startswith("|"):
            continue
        parts = [p.strip() for p in line.strip("|").split("|")]
        if len(parts) < 2:
            continue
        question = parts[1].strip()
        if question and question.lower() != "问题":
            out.add(question.lower())
    return out


def merge_entries_to_watchlist(watchlist_path: Path, entries: list[dict[str, Any]]) -> dict[str, Any]:
    if not watchlist_path.exists():
        raise FileNotFoundError(f"watchlist file not found: {watchlist_path}")
    lines = watchlist_path.read_text(encoding="utf-8").splitlines()
    existing = parse_existing_questions(lines)
    appended: list[str] = []
    merged_questions: list[str] = []
    skipped_questions: list[str] = []
    for e in entries:
        q = e["question"].strip()
        if q.lower() in existing:
            skipped_questions.append(q)
            continue
        category = e["category"]
        end_date = e["end_date"]
        watch_level = str(e.get("watch_level", "normal")).strip().lower()
        threshold_abs_pp = e.get("threshold_abs_pp")
        threshold_text = ""
        if isinstance(threshold_abs_pp, (int, float)) and float(threshold_abs_pp) > 0:
            threshold_text = f"{float(threshold_abs_pp):.2f}"
        row = (
            f"| {category} | {q.replace('|', '/')} | 0.00% | $0 | $0 | {end_date} | "
            f"{watch_level} | {threshold_text} |"
        )
        appended.append(row)
        existing.add(q.lower())
        merged_questions.append(q)
    if not merged_questions:
        return {
            "merged_count": 0,
            "skipped_count": len(skipped_questions),
            "merged_questions": [],
            "skipped_questions": skipped_questions,
        }
    content = "\n".join(lines) + "\n\n" + "\n".join(appended) + "\n"
    watchlist_path.write_text(content, encoding="utf-8")
    return {
        "merged_count": len(merged_questions),
        "skipped_count": len(skipped_questions),
        "merged_questions": merged_questions,
        "skipped_questions": skipped_questions,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Pull Notion manual watchlist entries")
    parser.add_argument("--parent-page-id", required=True, help="Notion parent page id")
    parser.add_argument("--root-page-title", default="SignalRadar", help="SignalRadar directory page title")
    parser.add_argument("--title-hint", default="SignalRadar_Manual_Entries", help="Manual entries child page title")
    parser.add_argument("--watchlist", required=True, help="Watchlist markdown path")
    parser.add_argument("--out-json", default="", help="Optional output json path")
    parser.add_argument("--auto-create-page", action="store_true", help="Auto create manual entry page when missing")
    args = parser.parse_args()

    watchlist_path = Path(args.watchlist)
    out_json_path = Path(args.out_json) if args.out_json else None

    try:
        headers = notion_headers()
    except ValueError as exc:
        return emit_error(
            "SR_PERMISSION_DENIED",
            f"notion auth missing: {exc}",
            retryable=False,
            details={"script": "pull_notion_watchlist_entries.py"},
        )

    try:
        root_title_candidates = [args.root_page_title] if args.root_page_title else []
        root_title_candidates.extend(DEFAULT_ROOT_TITLE_CANDIDATES)
        root_page_id = find_child_page_id(args.parent_page_id, headers, root_title_candidates)
        if not root_page_id and args.auto_create_page:
            root_page_id = create_child_page(args.parent_page_id, headers, args.root_page_title)
            if root_page_id:
                try:
                    seed_root_page_if_empty(root_page_id, headers)
                except Exception:
                    pass
        if not root_page_id:
            root_page_id = args.parent_page_id

        manual_title_candidates = [args.title_hint] if args.title_hint else []
        manual_title_candidates.extend(DEFAULT_TITLE_CANDIDATES)
        manual_page_id = find_child_page_id(root_page_id, headers, manual_title_candidates)
        migration_note = ""
        if not manual_page_id and root_page_id != args.parent_page_id:
            legacy_page_id = find_child_page_id(args.parent_page_id, headers, manual_title_candidates)
            if legacy_page_id:
                if move_page_to_parent(legacy_page_id, root_page_id, headers):
                    manual_page_id = legacy_page_id
                    migration_note = f" MIGRATED={legacy_page_id}"
                elif args.auto_create_page:
                    legacy_lines = extract_manual_candidate_lines(legacy_page_id, headers)
                    manual_page_id = create_manual_page(root_page_id, headers, args.title_hint)
                    if manual_page_id:
                        if legacy_lines:
                            try:
                                append_manual_entry_lines(manual_page_id, headers, legacy_lines)
                            except Exception:
                                pass
                        archive_page(legacy_page_id, headers)
                        migration_note = f" MIGRATED={legacy_page_id}"

        if not manual_page_id:
            if args.auto_create_page:
                manual_page_id = create_manual_page(root_page_id, headers, args.title_hint)
                if manual_page_id:
                    print(f"DIRECTORY_PAGE={root_page_id} SOURCE_PAGE_CREATED:{manual_page_id}")
                    return 0
            print(f"DIRECTORY_PAGE={root_page_id} NO_SOURCE_PAGE")
            return 0

        try:
            archive_legacy_top_level_pages(args.parent_page_id, root_page_id, headers, manual_title_candidates)
        except Exception:
            pass

        if args.auto_create_page:
            try:
                if seed_manual_page_if_empty(manual_page_id, headers):
                    print(f"DIRECTORY_PAGE={root_page_id} SOURCE_PAGE_SEEDED:{manual_page_id}")
                    return 0
            except Exception:
                pass
            try:
                ensure_manual_page_header(manual_page_id, headers)
            except Exception:
                pass

        blocks = list_block_children(manual_page_id, headers)
        lines = [extract_line_from_block(b) for b in blocks]
        lines = [x for x in lines if x]
        entries = parse_manual_entries(lines)
        if not entries:
            if out_json_path is not None:
                payload = {
                    "ts": utc_now(),
                    "parent_page_id": args.parent_page_id,
                    "root_page_id": root_page_id,
                    "manual_page_id": manual_page_id,
                    "title_hint": args.title_hint,
                    "entries_total": 0,
                    "entries_merged": 0,
                    "entries_skipped_existing": 0,
                    "entries": [],
                    "merged_questions": [],
                    "skipped_questions": [],
                    "watchlist": str(watchlist_path),
                    "status": "NO_VALID_LINES",
                }
                out_json_path.parent.mkdir(parents=True, exist_ok=True)
                out_json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            print(f"DIRECTORY_PAGE={root_page_id} MANUAL_PAGE={manual_page_id}{migration_note} NO_VALID_LINES")
            return 0

        merge_result = merge_entries_to_watchlist(watchlist_path, entries)
        merged = int(merge_result["merged_count"])
        skipped = int(merge_result["skipped_count"])
        payload = {
            "ts": utc_now(),
            "parent_page_id": args.parent_page_id,
            "root_page_id": root_page_id,
            "manual_page_id": manual_page_id,
            "title_hint": args.title_hint,
            "entries_total": len(entries),
            "entries_merged": merged,
            "entries_skipped_existing": skipped,
            "entries": entries,
            "merged_questions": merge_result["merged_questions"],
            "skipped_questions": merge_result["skipped_questions"],
            "watchlist": str(watchlist_path),
        }
        if out_json_path is not None:
            out_json_path.parent.mkdir(parents=True, exist_ok=True)
            out_json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        skip_hint = ""
        if skipped > 0:
            hint_list = merge_result["skipped_questions"][:3]
            skip_hint = f" SKIPPED={skipped} EXISTING={'; '.join(hint_list)}"
        print(
            f"DIRECTORY_PAGE={root_page_id} MANUAL_PAGE={manual_page_id}{migration_note} "
            f"MERGED={merged} TOTAL={len(entries)}{skip_hint}"
        )
        return 0
    except Exception as exc:  # noqa: BLE001
        return emit_error(
            "SR_SOURCE_UNAVAILABLE",
            f"notion pull failed: {exc}",
            retryable=True,
            details={"script": "pull_notion_watchlist_entries.py", "parent_page_id": args.parent_page_id},
        )


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""SignalRadar market normalization helpers.

v0.8.0 note:
- orchestration lives in signalradar.py
- this module remains as a compatibility helper for tests and older imports
"""

from __future__ import annotations

import json
import re
from datetime import datetime, timezone
from typing import Any


def as_percent(value: Any) -> float | None:
    """Convert probability value to 0-100 percentage."""
    if value is None:
        return None
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    if v <= 1.0:
        return round(v * 100.0, 6)
    return round(v, 6)


def first_non_null(item: dict[str, Any], keys: list[str]) -> Any:
    for key in keys:
        if key in item and item[key] is not None:
            return item[key]
    return None


def slugify(text: str) -> str:
    lowered = text.strip().lower()
    lowered = re.sub(r"[^a-z0-9]+", "-", lowered)
    return lowered.strip("-") or "unknown"


def extract_probability(item: dict[str, Any]) -> float | None:
    """Extract Yes outcome probability as percentage (0-100)."""
    val = first_non_null(
        item,
        ["probability", "current", "price", "lastPrice", "yesPrice", "lastTradePrice"],
    )
    p = as_percent(val)
    if p is not None:
        return p
    outcome_prices = item.get("outcomePrices")
    if isinstance(outcome_prices, str) and outcome_prices.startswith("["):
        try:
            outcome_prices = json.loads(outcome_prices)
        except (json.JSONDecodeError, ValueError):
            outcome_prices = None
    if isinstance(outcome_prices, list) and outcome_prices:
        return as_percent(outcome_prices[0])
    return None


def normalize_item(item: dict[str, Any]) -> dict[str, Any] | None:
    """Normalize a raw Polymarket market item to standard format."""
    market_id = first_non_null(item, ["id", "market_id", "marketId", "conditionId"])
    question = first_non_null(item, ["question", "title", "name"])
    if market_id is None or not question:
        return None
    probability = extract_probability(item)
    if probability is None:
        return None

    event_id = str(
        first_non_null(item, ["event_id", "eventId", "event", "parentEvent", "eventSlug", "id"]) or market_id
    )
    status = str(first_non_null(item, ["status", "state"]) or "active")
    if "active" in item and item.get("active") is False:
        status = "inactive"
    end_date = first_non_null(item, ["endDate", "end_date", "closeTime", "endDateIso"])

    return {
        "source": "polymarket",
        "market_id": str(market_id),
        "event_id": str(event_id),
        "slug": str(item.get("slug") or slugify(str(question))),
        "question": str(question),
        "probability": probability,
        "status": status.lower(),
        "end_date": end_date,
        "ts": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
    }

