# Onboarding: 3-step code-enforced flow (terminal / text mode)
# ---------------------------------------------------------------------------

def _onboarding(args: argparse.Namespace) -> int:
    """First-time setup with 6 preset events. 3-step interactive flow."""

    print("📡 Welcome to SignalRadar! Loading popular events...\n")

    # Resolve all preset URLs
    events_data: list[dict[str, Any]] = []
    for url in ONBOARDING_URLS:
        slug = parse_polymarket_url(url)
        if not slug:
            continue
        result = resolve_event(slug)
        if result["ok"]:
            markets = [m for m in result["markets"] if not is_settled(m)]
            events_data.append({
                "title": result["event_title"],
                "slug": result["slug"],
                "event_id": result["event_id"],
                "markets": markets,
                "url": url,
            })
        else:
            events_data.append({
                "title": slug.replace("-", " ").title(),
                "slug": slug,
                "event_id": "",
                "markets": [],
                "url": url,
                "unavailable": True,
            })

    if not events_data:
        print("Error: Could not load any preset events. Check network connection.")
        return 1

    # --- STEP 1: Show event titles + market counts ---
    print(f"🔢 Found {len(events_data)} events:\n")
    for i, ev in enumerate(events_data, 1):
        market_count = len(ev["markets"])
        unavail = " (unavailable)" if ev.get("unavailable") else ""
        suffix = f"({market_count} market{'s' if market_count != 1 else ''})"
        print(f"  {i}. {ev['title']}  {suffix}{unavail}")

    print()
    user_input = input("Enter numbers to REMOVE (e.g. 1,5), or press Enter to keep all: ").strip()

    # Parse removal choices
    remove_set: set[int] = set()
    if user_input:
        for part in user_input.replace(" ", ",").split(","):
            part = part.strip()
            if part.isdigit():
                remove_set.add(int(part))

    # Filter events
    kept_events = []
    for i, ev in enumerate(events_data, 1):
        if i not in remove_set and not ev.get("unavailable") and ev["markets"]:
            kept_events.append(ev)

    if not kept_events:
        print("\nNo events selected. You can add markets later with: signalradar.py add <url>")
        return 0

    # --- STEP 2: Show sub-market details, confirm ---
    total_markets = sum(len(ev["markets"]) for ev in kept_events)
    print(f"\n🔄 Adding {len(kept_events)} events ({total_markets} markets):\n")

    # Group by inferred category
    num = 0
    for ev in kept_events:
        for m in ev["markets"]:
            num += 1
            print(f"  {num}. {m['question']}  {m['probability']:.0f}%")
    print()

    answer = input(f"Confirm adding {total_markets} markets? (Y/n): ").strip().lower()
    if answer in ("n", "no"):
        print("Cancelled. You can add markets later with: signalradar.py add <url>")
        return 0

    # --- STEP 3: Add entries + show results ---
    now = _utc_now()
    wl_path = _watchlist_path()
    baseline_dir = _baseline_dir()
    all_new_entries = []

    for ev in kept_events:
        category = _infer_category(ev["title"])
        for m in ev["markets"]:
            entry = {
                "entry_id": m["entry_id"],
                "slug": m["slug"],
                "event_title": ev["title"],
                "question": m["question"],
                "category": category,
                "url": m["url"],
                "end_date": m.get("end_date", ""),
                "added_at": now,
            }
            all_new_entries.append((entry, m["probability"]))

    entries_to_add = [e for e, _ in all_new_entries]
    added, skipped = add_entries(wl_path, entries_to_add)

    # Record baselines
    for entry, prob in all_new_entries:
        if entry in added:
            check_entry(
                entry_id=entry["entry_id"],
                question=entry["question"],
                current_prob=prob,
                baseline_dir=baseline_dir,
                threshold_abs_pp=5.0,
                dry_run=False,
            )

    print(f"\n✅ Done! {len(added)} markets added, baselines recorded.")
    if skipped:
        print(f"⚠️ ({len(skipped)} already in watchlist, skipped)")
    print("📎 Remove any you don't need with: signalradar.py remove <number>")
    if added:
        _persist_detected_language_if_needed(getattr(args, "config", ""))

    print(
        "\nWhat is a baseline?\n"
        "A baseline is the \"last known probability\" SignalRadar records. When probability\n"
        "changes by more than the threshold (default 5pp) and a notification is sent,\n"
        "the baseline updates to the new value. Example:\n"
        "  baseline 7% -> probability rises to 15% -> alert sent -> baseline updates to 15%\n"
        "  Next alert requires another 5pp change from 15%."
    )

    # Auto-monitoring: enable after successful onboarding
    if added:
        _ensure_auto_monitoring(interval=10, config_override=getattr(args, "config", ""))

    return 0


def _infer_category(title: str) -> str:
    """Simple keyword-based category for onboarding events."""
    lower = title.lower()
    ai_keywords = ["gpt", "claude", "ai", "model", "llm", "openai", "anthropic", "gemini", "grok"]
    crypto_keywords = ["bitcoin", "btc", "ethereum", "eth", "crypto", "token"]
    if any(k in lower for k in ai_keywords):
        return "AI"
    if any(k in lower for k in crypto_keywords):
        return "crypto"
    return "default"


# ---------------------------------------------------------------------------
# CLI entry point
# ---------------------------------------------------------------------------

def _normalize_argv(argv: list[str]) -> list[str]:
    """Allow --yes/-y and --config before or after subcommand.

    Moves global flags that appear before the subcommand to after it,
    so argparse subparsers can parse them correctly.
    """
    commands = {"doctor", "add", "list", "show", "remove", "run", "config", "schedule", "digest"}
    # Find subcommand position
    cmd_idx = None
    for i, arg in enumerate(argv):
        if arg in commands:
            cmd_idx = i
            break
    if cmd_idx is None:
        return argv  # no subcommand found, let argparse handle the error

    # Move --yes/-y/--config from before subcommand to after
    before = argv[:cmd_idx]
    after = argv[cmd_idx:]
    relocated = []
    remaining = []
    skip_next = False
    for i, arg in enumerate(before):
        if skip_next:
            skip_next = False
            continue
        if arg in ("--yes", "-y"):
            relocated.append(arg)
        elif arg == "--config":
            relocated.append(arg)
            if i + 1 < len(before):
                relocated.append(before[i + 1])
                skip_next = True
        else:
            remaining.append(arg)
    # Insert relocated flags after the subcommand name
    return remaining + [after[0]] + relocated + after[1:]


def _emit_startup_notices(args: argparse.Namespace) -> None:
    # Capture reply route from OpenClaw foreground env if present
    _capture_reply_route()

    notices = _ensure_user_data_ready()
    if not notices:
        return
    stream = sys.stderr if getattr(args, "output", "text") in ("json", "openclaw") else sys.stdout
    for notice in notices:
        print(notice, file=stream)


def main() -> int:
    parser = argparse.ArgumentParser(
        description=f"SignalRadar v{__version__} — Polymarket probability monitor"
    )

    sub = parser.add_subparsers(dest="command", required=True)

    # doctor
    p_doc = sub.add_parser("doctor", help="Check runtime health")
    p_doc.add_argument("--output", choices=["text", "json"], default="text")
    p_doc.add_argument("--config", default="", help="Path to config JSON")

    # add
    p_add = sub.add_parser("add", help="Add market(s) by Polymarket URL")
    p_add.add_argument("url", nargs="?", default="", help="Polymarket event URL (omit for guided setup)")
    p_add.add_argument("--category", default="", help="Category for the entries")
    p_add.add_argument("--yes", "-y", action="store_true", default=False, help="Skip confirmation")
    p_add.add_argument("--output", choices=["text", "json"], default="text")
    p_add.add_argument("--config", default="", help="Path to config JSON")

    # list
    p_list = sub.add_parser("list", help="List watchlist entries")
    p_list.add_argument("--category", default="", help="Filter by category")
    p_list.add_argument("--archived", action="store_true", help="Show archived entries")
    p_list.add_argument("--output", choices=["json", "text"], default="text", help="Output format")

    # show
    p_show = sub.add_parser("show", help="Show current probability for one monitored market")
    p_show.add_argument("target", help="List number or keyword to match a monitored market")
    p_show.add_argument("--output", choices=["text", "json"], default="text")
    p_show.add_argument("--config", default="", help="Path to config JSON")

    # remove
    p_rm = sub.add_parser("remove", help="Remove entry by number")
    p_rm.add_argument("number", type=int, help="Entry number from 'list'")
    p_rm.add_argument("--yes", "-y", action="store_true", default=False, help="Skip confirmation")

    # config
    p_cfg = sub.add_parser("config", help="View or change settings")
    p_cfg.add_argument("key", nargs="?", default="", help="Setting name (e.g. check_interval_minutes)")
    p_cfg.add_argument("value", nargs="?", default=None, help="New value")
    p_cfg.add_argument("--output", choices=["text", "json"], default="text")
    p_cfg.add_argument("--config", default="", help="Path to config JSON")

    # schedule
    p_sched = sub.add_parser("schedule", help="Manage auto-monitoring schedule")
    p_sched.add_argument("action", nargs="?", default="", help="Interval in minutes, or 'disable'")
    p_sched.add_argument("--driver", choices=["auto", "crontab", "openclaw"], default="auto",
                         help="Scheduling driver (default: auto, prefers OpenClaw)")
    p_sched.add_argument("--output", choices=["text", "json"], default="text")
    p_sched.add_argument("--config", default="", help="Path to config JSON")

    # digest
    p_digest = sub.add_parser("digest", help="Preview or send periodic digest")
    p_digest.add_argument("--dry-run", action="store_true", help="Preview only, do not update state")
    p_digest.add_argument("--force", action="store_true", help="Ignore schedule timing and send now")
    p_digest.add_argument("--output", choices=["text", "json", "openclaw"], default="text")
    p_digest.add_argument("--config", default="", help="Path to config JSON")

    # onboard
    p_onboard = sub.add_parser("onboard", help="First-time guided setup (multi-step, bot mode)")
    p_onboard.add_argument("--step", choices=["preview", "confirm", "finalize"], required=True,
                           help="Onboarding step to execute")
    p_onboard.add_argument("--keep", default="all",
                           help="Comma-separated event indices to keep (step confirm), or 'all'")
    p_onboard.add_argument("--output", choices=["text", "json"], default="json")
    p_onboard.add_argument("--config", default="", help="Path to config JSON")

    # run
    p_run = sub.add_parser("run", help="Check all entries for probability changes")
    p_run.add_argument("--dry-run", action="store_true", help="No side effects")
    p_run.add_argument("--output", choices=["text", "json", "openclaw"], default="text")
    p_run.add_argument("--yes", "-y", action="store_true", default=False, help="Skip confirmation")
    p_run.add_argument("--push", action="store_true", default=False,
                       help="Push results via openclaw message send (for crontab driver, zero LLM cost)")
    p_run.add_argument("--config", default="", help="Path to config JSON")

    args = parser.parse_args(_normalize_argv(sys.argv[1:]))
    _emit_startup_notices(args)

    # Dispatch
    cmd = args.command
    if cmd == "doctor":
        return cmd_doctor(args)
    elif cmd == "add":
        return cmd_add(args)
    elif cmd == "list":
        return cmd_list(args)
    elif cmd == "show":
        return cmd_show(args)
    elif cmd == "remove":
        return cmd_remove(args)
    elif cmd == "config":
        return cmd_config(args)
    elif cmd == "schedule":
        return cmd_schedule(args)
    elif cmd == "digest":
        return cmd_digest(args)
    elif cmd == "onboard":
        return cmd_onboard(args)
    elif cmd == "run":
        return cmd_run(args)
    else:
        parser.print_help()
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prepublish gate for SignalRadar v0.5.3.

Verifies SignalRadar is in a publishable state:
1) Package hygiene (no internal docs, no personal paths)
2) doctor → HEALTHY
3) run --dry-run --yes --output json → valid output contract
4) Document consistency (negative + positive assertions)
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any


def _find_skill_dir() -> Path:
    """Locate the signalradar skill directory."""
    return Path(__file__).resolve().parent.parent


def _find_cli_script() -> str:
    return str(Path(__file__).resolve().parent / "signalradar.py")


def run_doctor(timeout_sec: int) -> tuple[bool, dict[str, Any]]:
    cli = _find_cli_script()
    cmd = [sys.executable, cli, "doctor", "--output", "json"]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_sec, check=False)
        if proc.returncode != 0:
            return False, {"status": "error", "error": ((proc.stderr or "") + (proc.stdout or ""))[-500:]}
        payload = json.loads((proc.stdout or "").strip() or "{}")
        ok = str(payload.get("status", "")).upper() == "HEALTHY"
        return ok, {"status": "ok" if ok else "warn", "payload": payload}
    except Exception as exc:
        return False, {"status": "error", "error": str(exc)}


def run_dry(timeout_sec: int) -> tuple[bool, dict[str, Any]]:
    cli = _find_cli_script()
    cmd = [sys.executable, cli, "--yes", "run", "--dry-run", "--output", "json"]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_sec, check=False)
        stdout = (proc.stdout or "").strip()
        # Parse JSON output — we accept any valid structured output
        # even if returncode != 0 (e.g. partial API errors)
        try:
            payload = json.loads(stdout or "{}")
        except json.JSONDecodeError:
            return False, {"status": "error", "error": f"invalid JSON output (rc={proc.returncode})"}
        st = str(payload.get("status", ""))
        # Frozen contract: status must be one of these
        if st not in ("NO_REPLY", "HIT", "ERROR"):
            return False, {"status": "error", "error": f"invalid run status: {st}"}
        # Check frozen fields exist
        for field in ("status", "request_id", "ts", "hits", "errors"):
            if field not in payload:
                return False, {"status": "error", "error": f"missing frozen field: {field}"}
        return True, {"status": "ok", "run_status": st}
    except subprocess.TimeoutExpired:
        return False, {"status": "error", "error": "timeout"}
    except Exception as exc:
        return False, {"status": "error", "error": str(exc)}


def check_package_hygiene() -> tuple[bool, dict[str, Any]]:
    """Check published skill directory for internal/private files."""
    skill_dir = _find_skill_dir()
    if not skill_dir.is_dir():
        return False, {"status": "error", "error": f"skill dir not found: {skill_dir}"}

    issues: list[str] = []

    # Disallowed directories
    for d in ["dev-docs", "session_logs"]:
        p = skill_dir / d
        if p.is_dir():
            files = list(p.glob("*.md"))
            if files:
                issues.append(f"directory '{d}/' contains {len(files)} files")

    # References internal docs check
    refs = skill_dir / "references"
    if refs.is_dir():
        for f in refs.iterdir():
            if not f.is_file():
                continue
            for pattern in ["devspec", "runbook", "checklist", "publishing_guide", "lesson"]:
                if pattern in f.name.lower():
                    issues.append(f"references/{f.name} looks like internal dev doc")

    # Sensitive path scan
    skip_dirs = {"__pycache__", ".git", "cache", "node_modules"}
    self_name = Path(__file__).name
    for root_path, dirs, filenames in os.walk(skill_dir):
        dirs[:] = [d for d in dirs if d not in skip_dirs]
        for fname in filenames:
            if fname == self_name:
                continue
            if not fname.endswith((".py", ".sh", ".md", ".json")):
                continue
            fpath = Path(root_path) / fname
            try:
                content = fpath.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            rel = fpath.relative_to(skill_dir)
            for personal_prefix in ["/Users/", "/home/"]:
                if personal_prefix in content:
                    issues.append(f"{rel}: contains personal path ({personal_prefix})")

    if issues:
        return False, {"status": "fail", "issues": issues}
    return True, {"status": "ok"}


def check_doc_consistency() -> tuple[bool, dict[str, Any]]:
    """Check document consistency: negative assertions (old wording removed) + positive assertions."""
    skill_dir = _find_skill_dir()
    issues: list[str] = []

    def _file_contains(rel_path: str, needle: str) -> bool:
        fp = skill_dir / rel_path
        if not fp.exists():
            return False
        try:
            return needle in fp.read_text(encoding="utf-8")
        except OSError:
            return False

    # --- Negative assertions (must NOT contain old wording) ---
    if _file_contains("SKILL.md", "Do NOT create cron"):
        issues.append("SKILL.md still contains old 'Do NOT create cron' prohibition")
    if _file_contains("SKILL.md", "does not create scheduled tasks automatically"):
        issues.append("SKILL.md still contains old 'does not create scheduled tasks' wording")
    if _file_contains("CLAUDE.md", "Create cron jobs automatically"):
        issues.append("CLAUDE.md still contains old 'Create cron jobs automatically' prohibition")

    # --- Positive assertions (must contain new wording) ---
    if not _file_contains("SKILL.md", "schedule"):
        issues.append("SKILL.md missing 'schedule' keyword")
    if not _file_contains("SKILL.md", "auto-monitoring") and not _file_contains("SKILL.md", "automatically enables"):
        issues.append("SKILL.md missing auto-monitoring declaration")
    if not _file_contains("README.md", "schedule"):
        issues.append("README.md missing 'schedule' keyword")

    if issues:
        return False, {"status": "fail", "issues": issues}
    return True, {"status": "ok"}


def main() -> int:
    parser = argparse.ArgumentParser(description="SignalRadar prepublish gate")
    parser.add_argument("--timeout", type=int, default=60, help="Timeout per command")
    parser.add_argument("--json", action="store_true", help="Machine-readable output")
    args = parser.parse_args()

    results: dict[str, dict[str, Any]] = {}
    all_ok = True

    # 1. Package hygiene
    ok, entry = check_package_hygiene()
    results["package_hygiene"] = entry
    if not ok:
        all_ok = False

    # 2. Doctor
    ok, entry = run_doctor(args.timeout)
    results["doctor"] = entry
    if not ok:
        all_ok = False

    # 3. Dry run
    ok, entry = run_dry(args.timeout)
    results["run_dry"] = entry
    if not ok:
        all_ok = False

    # 4. Document consistency
    ok, entry = check_doc_consistency()
    results["doc_consistency"] = entry
    if not ok:
        all_ok = False

    out: dict[str, Any] = {"ok": all_ok, "gate": "v0.5.3-prepublish", "results": results}
    if args.json:
        print(json.dumps(out, ensure_ascii=False))
    else:
        if all_ok:
            print("PREPUBLISH_PASS all checks ok")
        else:
            print("PREPUBLISH_FAIL")
            for k, v in results.items():
                if v.get("status") not in ("ok",):
                    print(f"  - {k}: {v.get('error') or v.get('issues') or v.get('status')}")
    return 0 if all_ok else 3


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Smoke test for SignalRadar v0.5.0 runtime connectivity.

Runs:
1) signalradar.py doctor --output json → HEALTHY
2) signalradar.py run --dry-run --output json --yes → valid JSON with status field

Pass condition: both exit 0 and return valid output.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any


def _find_cli_script() -> str:
    """Locate signalradar.py."""
    # Sibling in same directory
    here = Path(__file__).resolve().parent
    candidate = here / "signalradar.py"
    if candidate.is_file():
        return str(candidate)
    raise FileNotFoundError(f"signalradar.py not found in {here}")


def run_command(cmd: list[str], timeout_sec: int) -> tuple[bool, str]:
    """Run a command and return (ok, full_stdout)."""
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_sec, check=False)
        if proc.returncode != 0:
            return False, ((proc.stderr or "") + (proc.stdout or ""))[-500:]
        return True, (proc.stdout or "").strip()
    except subprocess.TimeoutExpired:
        return False, "timeout"
    except Exception as exc:
        return False, str(exc)


def main() -> int:
    parser = argparse.ArgumentParser(description="SignalRadar smoke test")
    parser.add_argument("--timeout", type=int, default=30, help="Timeout per command")
    parser.add_argument("--json", action="store_true", help="Machine-readable output")
    args = parser.parse_args()

    cli = _find_cli_script()
    results: dict[str, dict[str, Any]] = {}
    all_ok = True

    # Test 1: doctor
    ok, stdout = run_command([sys.executable, cli, "doctor", "--output", "json"], args.timeout)
    entry: dict[str, Any] = {"status": "ok" if ok else "error"}
    if ok:
        try:
            payload = json.loads(stdout)
            if payload.get("status") != "HEALTHY":
                ok = False
                entry["error"] = f"doctor status: {payload.get('status')}"
        except json.JSONDecodeError as e:
            ok = False
            entry["error"] = f"invalid JSON: {e}"
    else:
        entry["error"] = stdout[-500:]
    results["doctor"] = entry
    if not ok:
        all_ok = False

    # Test 2: run --dry-run --yes --output json
    ok, stdout = run_command(
        [sys.executable, cli, "--yes", "run", "--dry-run", "--output", "json"],
        args.timeout + 30,
    )
    entry = {"status": "ok" if ok else "error"}
    if ok:
        try:
            payload = json.loads(stdout)
            st = payload.get("status", "")
            if st not in ("NO_REPLY", "HIT"):
                ok = False
                entry["error"] = f"unexpected run status: {st}"
        except json.JSONDecodeError as e:
            ok = False
            entry["error"] = f"invalid JSON: {e}"
    else:
        entry["error"] = stdout[-500:]
    results["run_dry"] = entry
    if not ok:
        all_ok = False

    out = {"ok": all_ok, "results": results}
    if args.json:
        print(json.dumps(out, ensure_ascii=False))
    else:
        label = "SMOKE_OK" if all_ok else "SMOKE_FAIL"
        parts = " ".join(f"{k}={v.get('status')}" for k, v in results.items())
        print(f"{label} {parts}")
        if not all_ok:
            for k, v in results.items():
                if v.get("error"):
                    print(f"  - {k}: {v['error']}")
    return 0 if all_ok else 3


if __name__ == "__main__":
    sys.exit(main())
